'use strict';

// MODULES //

var isFunction = require( '@stdlib/assert/is-function' );
var isNumber = require( '@stdlib/assert/is-number' );
var isArray = require( '@stdlib/assert/is-array' );
var format = require( '@stdlib/string/format' );
var abs = require( '@stdlib/math/base/special/abs' );


// MAIN //

/**
* Finds a zero of a continuous function `f` on the interval `[a, b]`.
*
* @param {Function} f - objective function
* @param {number} a - lower bound
* @param {number} b - upper bound
* @param {number} maxIter - maximum number of iterations
* @param {number} xtol - absolute tolerance
* @param {number} rtol - relative tolerance
* @param {Array} args - array of arguments to be passed to f
* @throws {TypeError} first argument must be a function
* @throws {TypeError} second argument must be a number
* @throws {TypeError} third argument must be a number
* @throws {TypeError} fourth argument must be a number
* @throws {TypeError} fifth argument must be a number
* @throws {TypeError} sixth argument must be a number
* @throws {TypeError} seventh argument must be an array
* @throws {Error} function values at the interval endpoints must have opposite signs
* @returns {Object} solution object
*
* @example
* function f( x ) {
*     return x * x - 1.0;
* }
* var out = brentq( f, 0.0, 2.0, 100, 2e-12, 8.88e-16, [] );
* // returns { 'root': 1.0, ... }
*/
function brentq( f, a, b, maxIter, xtol, rtol, args ) {
	var funcalls;
	var delta;
	var nargs;
	var vargs;
	var xpre;
	var xcur;
	var xblk;
	var fpre;
	var fcur;
	var fblk;
	var spre;
	var scur;
	var sbis;
	var stry;
	var dpre;
	var dblk;
	var i;

	if ( !isFunction( f ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a function. Value: `%s`.', f ) );
	}
	if ( !isNumber( a ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a number. Value: `%s`.', a ) );
	}
	if ( !isNumber( b ) ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a number. Value: `%s`.', b ) );
	}
	if ( !isNumber( maxIter ) ) {
		throw new TypeError( format( 'invalid argument. Fourth argument must be a number. Value: `%s`.', maxIter ) );
	}
	if ( !isNumber( xtol ) ) {
		throw new TypeError( format( 'invalid argument. Fifth argument must be a number. Value: `%s`.', xtol ) );
	}
	if ( !isNumber( rtol ) ) {
		throw new TypeError( format( 'invalid argument. Sixth argument must be a number. Value: `%s`.', rtol ) );
	}
	if ( !isArray( args ) ) {
		throw new TypeError( format( 'invalid argument. Seventh argument must be an array. Value: `%s`.', args ) );
	}

	xpre = a;
	xcur = b;
	xblk = 0.0;
	fblk = 0.0;
	spre = 0.0;
	scur = 0.0;

	nargs = args.length;
	vargs = [ 0.0 ];
	for ( i = 0; i < nargs; i++ ) {
		vargs.push( args[ i ] );
	}

	vargs[ 0 ] = xpre;
	fpre = f.apply( null, vargs );

	vargs[ 0 ] = xcur;
	fcur = f.apply( null, vargs );
	funcalls = 2;

	if ( fpre === 0.0 ) {
		return {
			'root': xpre,
			'iterations': 0,
			'function_calls': funcalls,
			'converged': true,
			'flag': 'converged',
			'method': 'brentq'
		};
	}
	if ( fcur === 0.0 ) {
		return {
			'root': xcur,
			'iterations': 0,
			'function_calls': funcalls,
			'converged': true,
			'flag': 'converged',
			'method': 'brentq'
		};
	}
	if ( ( fpre > 0.0 && fcur > 0.0 ) || ( fpre < 0.0 && fcur < 0.0 ) ) {
		throw new Error( 'invalid arguments. Function values at the interval endpoints must have opposite signs.' );
	}

	for ( i = 0; i < maxIter; i++ ) {
		if (
			fpre !== 0.0 &&
			fcur !== 0.0 &&
			( ( ( fpre > 0.0 ) && ( fcur < 0.0 ) ) || ( ( fpre < 0.0 ) && ( fcur > 0.0 ) ) )
		) {
			// Signs are different
			xblk = xpre;
			fblk = fpre;
			spre = xcur - xpre;
			scur = spre;
		}
		if ( abs( fblk ) < abs( fcur ) ) {
			xpre = xcur;
			xcur = xblk;
			xblk = xpre;

			fpre = fcur;
			fcur = fblk;
			fblk = fpre;
		}

		// delta = ( xtol + rtol * abs(xcur) ) / 2;
		delta = ( xtol + ( rtol * abs( xcur ) ) ) / 2.0;

		sbis = ( xblk - xcur ) / 2.0;

		if ( fcur === 0.0 || abs( sbis ) < delta ) {
			return {
				'root': xcur,
				'iterations': i + 1,
				'function_calls': funcalls,
				'converged': true,
				'flag': 'converged',
				'method': 'brentq'
			};
		}

		if ( abs( spre ) > delta && abs( fcur ) < abs( fpre ) ) {
			if ( xpre === xblk ) {
				// Interpolate
				stry = ( -fcur * ( xcur - xpre ) ) / ( fcur - fpre );
			} else {
				// Extrapolate
				dpre = ( fpre - fcur ) / ( xpre - xcur );
				dblk = ( fblk - fcur ) / ( xblk - xcur );
				stry = ( -fcur * ( ( fblk * dblk ) - ( fpre * dpre ) ) ) /
					( dblk * dpre * ( fblk - fpre ) );
			}

			// Check if short step is acceptable
			// 2*fabs(stry) < MIN(fabs(spre), 3*fabs(sbis) - delta)
			if (
				2.0 * abs( stry ) <
				( ( abs( spre ) < ( ( 3.0 * abs( sbis ) ) - delta ) ) ?
					abs( spre ) :
					( ( 3.0 * abs( sbis ) ) - delta ) )
			) {
				// Good short step
				spre = scur;
				scur = stry;
			} else {
				// Bisect
				spre = sbis;
				scur = sbis;
			}
		} else {
			// Bisect
			spre = sbis;
			scur = sbis;
		}

		xpre = xcur;
		fpre = fcur;

		if ( abs( scur ) > delta ) {
			xcur += scur;
		} else {
			xcur += ( sbis > 0.0 ) ? delta : -delta;
		}

		vargs[ 0 ] = xcur;
		fcur = f.apply( null, vargs );
		funcalls += 1;
	}
	return {
		'root': xcur,
		'iterations': i,
		'function_calls': funcalls,
		'converged': false,
		'flag': 'suboptimal convergence',
		'method': 'brentq'
	};
}


// EXPORTS //

module.exports = brentq;
